/* ------------------------
Pre Loader
------------------------*/
#ht-preloader {
    background: #1e1d2d;
    bottom: 0;
    height: 100%;
    left: 0;
    overflow: hidden !important;
    position: fixed;
    right: 0;
    text-align: center;
    top: 0;
    width: 100%;
    z-index: 99999;
}

.loader {
    position: absolute;
    top: 50%;
    left: 0;
    width: 100%;
    text-align: center;
    margin: auto;
    transform: translateY(-50%);
    -webkit-transform: translateY(-50%);
    -o-transform: translateY(-50%);
    -ms-transform: translateY(-50%);
    -moz-transform: translateY(-50%);
}

.loader span {
    animation: moving 4s linear infinite;
    animation-delay: calc((var(--n) - 10) * 0.4s);
    font-size: 3.5em;
    color: #f34960;
    font-weight: 700;
}

@keyframes moving {
    0% {
        filter: opacity(0);
    }

    33% {
        filter: opacity(1);
    }

    66% {
        filter: opacity(1);
    }

    100% {
        filter: opacity(0);
    }
}

.loader span:nth-child(1) {
    --n: 1;
}

.loader span:nth-child(2) {
    --n: 2;
}

.loader span:nth-child(3) {
    --n: 3;
}

.loader span:nth-child(4) {
    --n: 4;
}

.loader span:nth-child(5) {
    --n: 5;
}

