/* ------------------------
    Accordion
------------------------*/
.accordion .accordion-item {
    background: none;
    position: relative;
    border: 1px solid rgba(0, 0, 0, 0.125);
}

.accordion .accordion-item .accordion-button {
    font-weight: 400;
    text-transform: capitalize;
    font-size: 1.125rem;
    padding: 0.5rem 1rem;
}

.accordion-button:focus {
    border-color: inherit;
    box-shadow: none;
}

.accordion .accordion-item .accordion-button:after {
    width: 20px;
    height: 20px;
    border-radius: 50%;
    text-align: center;
    line-height: 20px;
    background: #fcfbf7;
    content: '\f107';
    font-family: 'Line Awesome Free';
    font-weight: 900;
    font-size: 0.7rem;
    top: 50%;
    position: absolute;
    right: 0.5rem;
    margin-top: -10px;
}

.accordion .accordion-item .accordion-button[aria-expanded='true'] {
    color: #f34960;
}

.accordion .accordion-item .accordion-button[aria-expanded='true']:after {
    background: #f34960;
    color: #ffffff;
    transform: rotate(180deg);
}

.accordion .accordion-body {
    padding: 15px;
    line-height: 2;
}

.accordion .accordion-body li a {
    font-size: 0.9rem;
    color: #2f2f41;
}

/* ------------------------
Countdown
------------------------*/
.countdown {
    margin: 50px 0;
    width: 100%;
}

.countdown > li {
    font-weight: 700;
    list-style-type: none;
}

.countdown > li span {
    font-size: 70px;
    font-weight: 700;
    line-height: 80px;
    display: inline-block;
    color: #f34960;
}

.countdown > li p {
    font-size: 20px;
    display: block;
    line-height: 30px;
    margin-bottom: 0;
    color: #ffffff;
}

/* ------------------------
    Scroll to Top
------------------------*/
.scroll-top {
    -webkit-transform: translateY(-50%) rotate(90deg);
    /* -ms-transform: translateY(-50%) rotate(90deg); */
    transform: translateY(-50%) rotate(90deg);
    position: fixed;
    top: 50%;
    right: -20px;
    z-index: 600;
    opacity: 1;
    -webkit-transition: all 0.8s ease-in-out;
    transition: all 0.8s ease-in-out;
    cursor: pointer;
}

.scroll-top div,
.scroll-top div:visited {
    font-size: 14px;
    font-weight: 600;
    color: #2f2f41;
    display: block;
    text-transform: uppercase;
}

.scroll-top div:before {
    content: '\f309';
    font-family: 'Line Awesome Free';
    position: absolute;
    top: 50%;
    font-size: 2rem;
    color: #f34960;
    transform: translateY(-50%) rotate(90deg);
    left: -40px;
}

.scroll-top div:hover:before {
    left: -30px;
}

.scroll-top div:hover,
.scroll-top div:focus {
    color: #f34960;
}

.scroll-top.scroll-visible {
    opacity: 1;
    visibility: visible;
}

/* ------------------------
    Feature Box
------------------------*/
.feature-hover:before {
    width: 100%;
    height: 100%;
    /* background: #ffffff; */
    /* border-radius: 30% 90% 20% 30% / 30% 90% 30% 30%; */
    /* box-shadow: 0 10px 30px 5px rgba(1, 164, 121, 0.06); */
    content: '';
    position: absolute;
    left: 0;
    top: 0;
    z-index: -1;
    opacity: 0;
    transform: scale(0);
    transition: opacity 0.8s, transform 0.8s;
}

.feature-hover:hover:before,
.feature-hover.active:before {
    opacity: 1;
    transform: scale(1);
}

.feature-hover:hover .f-icon {
    animation: headShake 1.2s infinite;
    animation-duration: 5s;
    color: #f34960;
    position: relative;
}

.f-icon {
    font-size: 3.5rem;
    line-height: 3.5rem;
}

.f-icon-m {
    font-size: 2.7rem;
    line-height: 2.7rem;
}

.f-icon-s {
    font-size: 2rem;
    line-height: 2rem;
}

.list-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    display: inline-block;
}

/* ------------------------
   Testimonial
------------------------*/
.testimonial-carousel .carousel-inner {
    z-index: 9;
}

.testimonial-carousel .controls li {
    animation: leftRight 1.2s infinite;
    animation-duration: 5s;
    width: 70px;
    position: absolute;
    border-radius: 100%;
    z-index: 99;
}

.testimonial-carousel .controls li.active {
    width: auto;
}

.testimonial-carousel .controls li:nth-child(1) {
    left: 0;
    top: 0;
}

.testimonial-carousel .controls li:nth-child(2) {
    left: 10%;
    top: 30%;
}

.testimonial-carousel .controls li:nth-child(3) {
    left: 0;
    bottom: 30%;
    animation: topBottom 1.2s infinite;
    animation-duration: 5s;
}

.testimonial-carousel .controls li:nth-child(4) {
    left: 10%;
    bottom: 0;
}

.testimonial-carousel .controls li:nth-child(5) {
    right: 0;
    top: 0;
}

.testimonial-carousel .controls li:nth-child(6) {
    right: 10%;
    top: 30%;
}

.testimonial-carousel .controls li:nth-child(7) {
    right: 0;
    bottom: 30%;
    animation: topBottom 1.2s infinite;
    animation-duration: 5s;
}

.testimonial-carousel .controls li:nth-child(8) {
    right: 10%;
    bottom: 0;
}

