/* ------------------------
   Responsive
------------------------*/
@media (max-width: 991.98px) {
    .hero-shape3:before {
        height: 40%;
        top: -8%;
    }
}

@media (max-width: 767.98px) {
    h1,
    .h1 {
        font-size: calc(1.575rem + 3.9vw);
    }

    h2,
    .h2 {
        font-size: 2rem;
    }

    h2 span.d-block {
        display: inline !important;
    }

    .testimonial-carousel .controls li {
        width: 30% !important;
        text-align: center;
        margin-top: 1rem;
        position: relative;
        left: inherit !important;
        right: inherit !important;
        top: inherit !important;
        bottom: inherit !important;
    }

    .testimonial-carousel .controls li img {
        width: 60px;
    }

    .countdown > li span {
        font-size: 50px;
        line-height: 50px;
    }

    .countdown > li p {
        font-size: 16px;
        line-height: 24px;
    }
}

@media (max-width: 575.98px) {
    .countdown > li span {
        font-size: 35px;
        line-height: 35px;
    }

    .countdown > li p {
        font-size: 15px;
    }
}

